import FreeCAD

# Open the precondition file
doc = FreeCAD.open("/home/user/Precondition_Unnamed.FCStd")

print("=== Checking for Assembly/Joint objects ===\n")

for obj in doc.Objects:
    print(f"Object: {obj.Name}")
    print(f"  TypeId: {obj.TypeId}")

    # List all properties
    for prop in obj.PropertiesList:
        try:
            val = getattr(obj, prop)
            if not callable(val):
                print(f"    {prop}: {val}")
        except:
            pass

    print()

FreeCAD.closeDocument(doc.Name)
